  function testGraph(type,parameters,output){
    if(type==='anova2'){
      const entries=[['Factor A','FA','pA','dfA'],['Factor B','FB','pB','dfB'],...(output.FAB===undefined?[]:[['Interaction','FAB','pAB','dfAB']])];
      menu('ANOVA p-area',entries.map(([title,statistic,p,df])=>[title,()=>drawGraph({type:'Test',distribution:{kind:'F',operation:'cdf',parameters:{df1:output[df],df2:output.dfE},value:output[p],marker:output[statistic],intervals:[[output[statistic],Infinity]],title,label:'p'},back:()=>inferenceForm('tests',type)})]),()=>inferenceForm('tests',type));return;
    }
    const kind=['oneT','twoT','linearT'].includes(type)?'t':['chiGOF','chi2way'].includes(type)?'chi2':['twoF','anova1'].includes(type)?'F':'normal';
    const p=kind==='t'||kind==='chi2'?{df:output.df}:kind==='F'?{df1:output.df1,df2:output.df2}:{mu:0,sigma:1},statistic=output.statistic,tail=['chiGOF','chi2way','anova1'].includes(type)?'>':parameters.tail||'!=';let intervals;
    if(tail==='<')intervals=[[-Infinity,statistic]];else if(tail==='>')intervals=[[statistic,Infinity]];
    else if(kind==='normal'||kind==='t')intervals=[[-Infinity,-Math.abs(statistic)],[Math.abs(statistic),Infinity]];
    else {const area=output.p/2;if(area<=0)intervals=[];else{const lower=cgDistribution(kind,'inverse',{...p,p:area}),upper=cgDistribution(kind,'inverse',{...p,p:1-area});intervals=[[-Infinity,lower],[upper,Infinity]];}}
    drawGraph({type:'Test',distribution:{kind,operation:'cdf',parameters:p,value:output.p,marker:statistic,intervals,title:choices.tests[type],label:'p'},back:()=>inferenceForm('tests',type)});
  }

