  function zoomMenu(){const w={...ensureGraph()},base={...graphView};menu('ZOOM',[['IN',()=>zoom(.5)],['OUT',()=>zoom(2)],['AUTO',()=>drawGraph({...base,window:null})],['SQUARE',()=>{const half=(w.ymax-w.ymin)*384/216/2,c=(w.xmin+w.xmax)/2;drawGraph({...base,window:{...w,xmin:c-half,xmax:c+half}});}]],()=>drawGraph(base));function zoom(factor){const cx=(w.xmin+w.xmax)/2,cy=(w.ymin+w.ymax)/2,dx=(w.xmax-w.xmin)*factor/2,dy=(w.ymax-w.ymin)*factor/2;drawGraph({...base,window:{xmin:cx-dx,xmax:cx+dx,ymin:cy-dy,ymax:cy+dy}});}}
