      if(view==='lists'){
        if(headerSelected){
          if(formulaDraft&&['left','right'].includes(action)){formulaInput.focus();const caret=Math.max(0,Math.min(formulaInput.value.length,(formulaInput.selectionStart??0)+(action==='left'?-1:1)));formulaInput.setSelectionRange(caret,caret);return true;}
          if(formulaDraft&&safe(commitFormula)===false)return true;
          if(headerSelected){if(action==='down'){headerSelected=false;formulaDraft='';saved.selectedRow=0;renderLists();body.querySelector('[data-stat-value]').focus();}else if(action==='left'||action==='right')safe(()=>selectColumnHeader(Math.max(0,Math.min(25,saved.selectedList+(action==='left'?-1:1)))));return true;}
        }
        const editing=body.querySelector('[data-stat-value]');if(editing?.dataset.editing&&!safe(()=>commitCell(false)))return true;if(action==='up'&&saved.selectedRow===0){safe(()=>selectColumnHeader(saved.selectedList));return true;}saved.selectedList=Math.max(0,Math.min(25,saved.selectedList+(action==='left'?-1:action==='right'?1:0)));saved.selectedRow=Math.max(0,Math.min(998,saved.selectedRow+(action==='up'?-1:action==='down'?1:0)));persist();renderLists();return true;}
      if(view==='form'){const controls=[...body.querySelectorAll('input,select,textarea')].filter(el=>!el.closest('[hidden]'));const index=controls.indexOf(document.activeElement),delta=action==='up'||action==='left'?-1:1;controls[Math.max(0,Math.min(controls.length-1,index+delta))]?.focus();return true;}
