  function handleKey(event){if(/^F\d+$/.test(event.key)||event.key==='Home')return false;if(event.key==='Escape')return handleAction('back');if(event.key==='Enter'&&!(event.shiftKey&&event.target.tagName==='TEXTAREA'))return handleAction('execute');if((view==='graph'||view==='lists'&&(event.target.tagName!=='INPUT'||event.target.matches('[data-stat-value]')&&(!event.target.dataset.editing||['ArrowUp','ArrowDown'].includes(event.key))||event.target.matches('[data-stat-formula]')&&['ArrowUp','ArrowDown'].includes(event.key)))&&/^Arrow/.test(event.key))return handleAction(event.key.slice(5).toLowerCase());return false;}
